ALTER TABLE public.civic_settings ADD COLUMN event_reputation_gain integer NOT NULL DEFAULT 2, ADD COLUMN event_influence_gain integer NOT NULL DEFAULT 1, ADD COLUMN event_relation_gain integer NOT NULL DEFAULT 10, ADD COLUMN event_duration_minutes integer NOT NULL DEFAULT 60, ADD COLUMN event_energy_cost integer NOT NULL DEFAULT 8, ADD COLUMN event_start_hour integer NOT NULL DEFAULT 18;
CREATE OR REPLACE FUNCTION public.configure_civic_event() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.civic_settings; BEGIN IF NEW.civic THEN SELECT * INTO cfg FROM public.civic_settings WHERE id=1; NEW.reputation_gain:=cfg.event_reputation_gain; NEW.influence_gain:=cfg.event_influence_gain; NEW.relation_gain:=cfg.event_relation_gain; NEW.duration_minutes:=cfg.event_duration_minutes; NEW.energy_cost:=cfg.event_energy_cost; NEW.start_hour:=cfg.event_start_hour; END IF; RETURN NEW; END $$;
CREATE TRIGGER civic_event_configuration BEFORE INSERT ON public.organization_events FOR EACH ROW EXECUTE FUNCTION public.configure_civic_event(); REVOKE ALL ON FUNCTION public.configure_civic_event() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.guard_civic_decision_deadline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.decided_at>public.game_now() AND NEW.status='applied' THEN NEW.status:='planned'; END IF; RETURN NEW; END $$;
CREATE TRIGGER civic_decision_00_deadline BEFORE INSERT OR UPDATE OF status,decided_at ON public.public_decisions FOR EACH ROW EXECUTE FUNCTION public.guard_civic_decision_deadline(); REVOKE ALL ON FUNCTION public.guard_civic_decision_deadline() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.civic_actor() RETURNS public.characters LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Non connecté'; END IF; SELECT * INTO c FROM public.characters WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Personnage introuvable'; END IF; PERFORM public.settle_daily_life(c.id); INSERT INTO public.civic_stats(character_id) VALUES(c.id) ON CONFLICT DO NOTHING; PERFORM pg_advisory_xact_lock(hashtextextended('civic:'||c.city_id,0)); UPDATE public.public_decisions SET status='applied' WHERE city_id=c.city_id AND status='planned' AND decided_at<=public.game_now() AND applied_at IS NULL; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.civic_actor() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.civic_actor() TO service_role;
CREATE OR REPLACE FUNCTION public.guard_consultation_dates() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.ends_at<=NEW.starts_at THEN RAISE EXCEPTION 'La consultation doit se terminer après son début'; END IF; RETURN NEW; END $$; CREATE TRIGGER consultation_dates BEFORE INSERT OR UPDATE OF starts_at,ends_at ON public.consultations FOR EACH ROW EXECUTE FUNCTION public.guard_consultation_dates();
REVOKE ALL ON FUNCTION public.guard_consultation_dates() FROM PUBLIC,anon,authenticated;